// Produce a NEW-environment install from the reviewed business migrations.
// Never edit the historical Supabase migrations or rewrite existing accounts.
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
const preflight=`-- CloudBase PG v0.9: fresh environment only. Entire install is atomic.
-- Generated by tools/build-cloudbase.cjs. Enrollment and tasks stay CLOSED.
begin;
do $$begin
 if to_regclass('public.participant_profiles') is not null or to_regclass('private.pilot_settings') is not null then
  raise exception 'fresh_environment_required'; end if;
 if to_regclass('auth.users') is null or to_regprocedure('auth.uid()') is null or to_regprocedure('auth.jwt()') is null then
  raise exception 'cloudbase_pg_auth_required'; end if;
 if (select pg_get_function_result('auth.uid()'::regprocedure))<>'text' then raise exception 'cloudbase_text_identity_required'; end if;
 if not exists(select 1 from information_schema.columns where table_schema='auth' and table_name='users' and column_name in ('email_verified','email_confirmed_at','phone_number_verified','phone_verified','phone_confirmed_at')) then
  raise exception 'verified_contact_schema_review_required: run cloudbase/00_preflight.sql and review auth.users verification fields before installing'; end if;
end; $$;
`;
const helper=`
-- Only server-owned TOP-LEVEL verification fields are trusted. Never user_metadata.
-- Unknown auth schemas fail closed; presence of email/phone alone is insufficient.
create function private.cloudbase_verified_contact(u jsonb) returns boolean
language sql immutable set search_path='' as $$
 select coalesce(u->>'is_anonymous','false')<>'true' and (
  ((u->>'email_verified'='true' or nullif(u->>'email_confirmed_at','') is not null) and nullif(u->>'email','') is not null)
  or ((u->>'phone_number_verified'='true' or u->>'phone_verified'='true' or nullif(u->>'phone_confirmed_at','') is not null)
      and coalesce(nullif(u->>'phone_number',''),nullif(u->>'phone','')) is not null)
 ) is true;
$$;
revoke all on function private.cloudbase_verified_contact(jsonb) from public,anon,authenticated;
`;
function replaceExactly(text,from,to,count){const found=text.split(from).length-1;if(found!==count)throw new Error('CloudBase transform needs review: '+from+' count '+found);return text.split(from).join(to);}
function build(){
 const files=fs.readdirSync(path.join(root,'supabase/migrations')).filter(x=>/^\d{3}_.+\.sql$/.test(x)).sort();
 if(files.length!==8)throw new Error('Review new migrations before extending CloudBase install.');
 let sql=files.map(name=>'\n-- Source: '+name+'\n'+fs.readFileSync(path.join(root,'supabase/migrations',name),'utf8').replace(/^begin;\s*$/gm,'').replace(/^commit;\s*$/gm,'')).join('\n');
 sql=replaceExactly(sql,'user_id uuid','user_id varchar(64)',3);
 sql=replaceExactly(sql,'v_user uuid:=auth.uid()','v_user text:=auth.uid()',2);
 sql=replaceExactly(sql,'(u.email_confirmed_at is not null or u.phone_confirmed_at is not null)','private.cloudbase_verified_contact(to_jsonb(u))',2);
 sql=replaceExactly(sql,'revoke all on schema private from public, anon, authenticated;','revoke all on schema private from public, anon, authenticated;\n'+helper,1);
 sql=sql.replace('-- Run once in a new Supabase project.','-- Business schema adapted for a new CloudBase PG project.');
 return preflight+sql+"\nnotify pgrst, 'reload schema';\ncommit;\n";
}
if(require.main===module){const sql=build();fs.writeFileSync(path.join(root,'cloudbase/01_install.sql'),sql);console.log('CloudBase fresh-install SQL generated; no cloud changes made.');}
module.exports={build};
